const prisma = require('../../config/db');

/**
 * Notifications repository — ONLY database access lives here. No
 * authorization, no business rules. There are no createNotification /
 * updateNotification-content functions here at all — BR-11.1:
 * notifications are generated by their originating feature (e.g.
 * bookings, memberships), not by this module, so this repository only
 * ever reads Notification rows and mutates their read/resend state.
 */

// --- Helpers needed for authorization/scoping in the service ---------------

function findTrainerByUserId(userId) {
  return prisma.trainer.findUnique({ where: { user_id: userId } });
}

function findMemberByUserId(userId) {
  return prisma.member.findUnique({ where: { user_id: userId } });
}

// --- Notification ---------------------------------------------------------

function findNotificationById(id) {
  return prisma.notification.findUnique({ where: { id } });
}

function buildNotificationWhere({ recipient_user_id, notification_type, status }) {
  const where = {};
  const and = [];

  if (recipient_user_id) and.push({ recipient_user_id });
  if (notification_type) and.push({ notification_type });
  if (status) and.push({ status });

  if (and.length > 0) where.AND = and;
  return where;
}

async function findNotifications({ where, skip, take }) {
  const [items, total] = await Promise.all([
    prisma.notification.findMany({
      where,
      skip,
      take,
      orderBy: { created_at: 'desc' },
    }),
    prisma.notification.count({ where }),
  ]);

  return { items, total };
}

/**
 * BR-11.5: reading a notification changes only status and read_at — no
 * history table, no other fields touched.
 */
function markAsRead(id) {
  return prisma.notification.update({
    where: { id },
    data: { status: 'Read', read_at: new Date() },
  });
}

// --- NotificationAttempt (BR-11.4 / BR-11.6) --------------------------------

/**
 * Backs attempt_number computation: "attempt numbers are unique per
 * notification" (@@unique([notification_id, attempt_number])) — the
 * service needs to know the current highest attempt_number to compute
 * the next one. Returns null if no attempts exist yet, letting the
 * service start at 1.
 */
function findLatestAttempt(notificationId) {
  return prisma.notificationAttempt.findFirst({
    where: { notification_id: notificationId },
    orderBy: { attempt_number: 'desc' },
  });
}

/**
 * BR-11.6: manual resend creates a new NotificationAttempt row; existing
 * attempts are never modified. No update/delete function exists for
 * NotificationAttempt at all in this repository, by design.
 */
function createAttempt(data) {
  return prisma.notificationAttempt.create({ data });
}

function findAttemptsByNotification(notificationId) {
  return prisma.notificationAttempt.findMany({
    where: { notification_id: notificationId },
    orderBy: { attempt_number: 'asc' },
  });
}

module.exports = {
  findTrainerByUserId,
  findMemberByUserId,
  findNotificationById,
  buildNotificationWhere,
  findNotifications,
  markAsRead,
  findLatestAttempt,
  createAttempt,
  findAttemptsByNotification,
};